import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_d = 0
    my_d = 0
    last_ops = []
    for i in range(n):
        me, op = history[i]
        if op == 'D':
            opp_d += 1
        if me == 'D':
            my_d += 1
        if i >= n - 20:
            last_ops.append(op)

    last_me, last_op = history[-1]

    # Near endgame: protect against exploitation, exploit pure cooperators.
    if n >= 88:
        if opp_d == 0:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C' if opp_d * 4 <= n else 'D'

    # Pure cooperator (perturbed by forgiving probes)
    if opp_d == 0:
        # Small late-game probing to gain extra, but keep mostly C to sustain CC=3
        if n >= 60 and n % 7 == 0:
            return 'D'
        return 'C'

    defect_rate = opp_d / n
    recent_d = 0
    for x in last_ops:
        if x == 'D':
            recent_d += 1
    recent_len = len(last_ops)
    recent_dr = recent_d / recent_len if recent_len else 0.0

    # Long D-streak detection
    streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_d += 1
        else:
            break
    streak_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            streak_c += 1
        else:
            break

    # Almost pure defector: defect, with rare cheap probes
    if defect_rate >= 0.8 or (recent_dr >= 0.9 and recent_len >= 10):
        if rng.random() < 0.04:
            return 'C'
        return 'D'

    # Sustained defection handling (recent high D rate)
    if recent_dr >= 0.7:
        if streak_d >= 2:
            return 'D'
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Opponent just defected: retaliate but with calibrated forgiveness.
    if last_op == 'D':
        # If opponent has been mostly cooperative, high forgiveness to keep CC gains.
        if defect_rate < 0.15:
            if rng.random() < 0.75:
                return 'C'
            return 'D'
        if defect_rate < 0.35:
            if rng.random() < 0.45:
                return 'C'
            return 'D'
        # Mixed/chronic: punish reliably
        if streak_d >= 2:
            return 'D'
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Opponent just cooperated.
    # If we defected last, likely the opponent is forgiving; go back to C to keep CC gains.
    if last_me == 'D':
        return 'C'

    # Opponent is mostly cooperative: cooperate, with rare exploitation probes.
    if defect_rate < 0.2:
        # Occasional probe to detect exploitability, but low so we don't destabilize
        if n >= 30 and rng.random() < 0.03:
            return 'D'
        return 'C'

    # Mixed opponent: cooperate but keep occasional defensive defection to stay safe
    if defect_rate < 0.45:
        if rng.random() < 0.8:
            return 'C'
        return 'D'

    # Opponent leaning defective: defect more, occasional cooperative probe to recover
    if rng.random() < 0.15:
        return 'C'
    return 'D'
